// AG Grid v36. Master/Detail, Set Filter, Row Grouping and Excel Export are Enterprise features.
import { useMemo, useRef, useState } from "react";
import { AgGridProvider, AgGridReact } from "ag-grid-react";
import type { ColDef, GetRowIdParams } from "ag-grid-community";
import { AllEnterpriseModule } from "ag-grid-enterprise";

const modules = [AllEnterpriseModule];

interface OrderLine { sku: string; product: string; qty: number; unitPrice: number }
interface Order {
  orderId: string;
  customer: string;
  status: "New" | "Picking" | "Shipped" | "Cancelled";
  total: number;
  lines: OrderLine[];
}

export function OrdersGrid({ orders }: { orders: Order[] }) {
  const gridRef = useRef<AgGridReact<Order>>(null);
  const [search, setSearch] = useState("");

  const columnDefs = useMemo<ColDef<Order>[]>(() => [
    { field: "orderId", cellRenderer: "agGroupCellRenderer" },
    { field: "customer", enableRowGroup: true },
    {
      field: "status",
      filter: "agSetColumnFilter",
      enableRowGroup: true,
      editable: true,
      cellEditor: "agSelectCellEditor",
      cellEditorParams: { values: ["New", "Picking", "Shipped", "Cancelled"] },
    },
    { field: "total", valueFormatter: (p) => (p.value == null ? "" : p.value.toFixed(2)) },
  ], []);

  const detailCellRendererParams = useMemo(() => ({
    detailGridOptions: {
      columnDefs: [{ field: "sku" }, { field: "product" }, { field: "qty" }, { field: "unitPrice" }],
    },
    getDetailRowData: (params: { data: Order; successCallback: (rows: OrderLine[]) => void }) =>
      params.successCallback(params.data.lines),
  }), []);

  return (
    <AgGridProvider modules={modules}>
      <input placeholder="Search orders" value={search} onChange={(e) => setSearch(e.target.value)} />
      <button onClick={() => gridRef.current?.api.exportDataAsExcel({ fileName: "orders.xlsx" })}>
        Export to Excel
      </button>
      <div style={{ height: 500 }}>
        <AgGridReact<Order>
          ref={gridRef}
          rowData={orders}
          columnDefs={columnDefs}
          getRowId={(p: GetRowIdParams<Order>) => p.data.orderId}
          masterDetail={true}
          detailCellRendererParams={detailCellRendererParams}
          rowGroupPanelShow="always"
          quickFilterText={search}
        />
      </div>
    </AgGridProvider>
  );
}
